namespace BARANG.Backoffice.Components.Help;

public sealed record HelpNode(
    string Id,
    string Fa, string En, string Ar,
    string? Route,
    string FaPurpose, string EnPurpose, string ArPurpose,
    string FaFeatures = "", string EnFeatures = "", string ArFeatures = "",
    IReadOnlyList<HelpNode>? Children = null)
{
    public string Name(string culture) => culture switch { "en" => En, "ar" => Ar, _ => Fa };
    public string Purpose(string culture) => culture switch { "en" => EnPurpose, "ar" => ArPurpose, _ => FaPurpose };
    public string Features(string culture) => culture switch { "en" => EnFeatures, "ar" => ArFeatures, _ => FaFeatures };
}

public static class HelpCatalog
{
    private static HelpNode N(string id, string fa, string en, string ar, string? route,
        string faP, string enP, string arP, string faF, string enF, string arF, HelpNode[]? children = null)
        => new(id, fa, en, ar, route, faP, enP, arP, faF, enF, arF, children);

    private static string Lf(string usage) => "• افزودن، ویرایش و فعال/غیرفعال‌سازی موارد این فهرست از همین صفحه\n• جستجوی سریع میان موارد و ثبت عنوان‌ها به سه زبان فارسی، عربی و انگلیسی\n" + usage.Replace("•", "\n•").TrimStart('\n');
    private static string Le(string usage) => "• Add, edit and enable/disable items of this list right from this page\n• Fast search across items and trilingual titles (fa/ar/en)\n" + usage.Replace("•", "\n•").TrimStart('\n');
    private static string La(string usage) => "• إضافة وتعديل وتفعيل/تعطيل بنود هذه القائمة من نفس الصفحة\n• بحث سريع بين البنود وعناوين بثلاث لغات\n" + usage.Replace("•", "\n•").TrimStart('\n');

